sources.code:
tasks = [
    {"task_id": "t1", "expected": "refund issued"},
    {"task_id": "t2", "expected": "order shipped"},
    {"task_id": "t3", "expected": "Account Closed"},
]
outputs = {"t1": "refund issued", "t2": "Order shipped", "t3": "Account Closed"}

def exact_match(expected, output):
    return {"correct": expected == output}

results = []
for t in tasks:
    r = exact_match(t["expected"], outputs[t["task_id"]])
    results.append((t["task_id"], r["correct"]))
    print(t["task_id"], r)
print("accuracy:", sum(c for _, c in results) / len(results))

sources.output:
t1 {'correct': True}
t2 {'correct': False}
t3 {'correct': True}
accuracy: 0.6666666666666666

